public int MaxDepth(TreeNode root) =>
    root == null ? 0 : 1 + Math.Max(MaxDepth(root.left), MaxDepth(root.right));

// тот же код по шагам шаблона
int Depth(TreeNode node) {
    if (node == null) return 0;          // 1. ответ для пустого
    int l = Depth(node.left);            // 2. спросить детей
    int r = Depth(node.right);
    return 1 + Math.Max(l, r);           // 3. собрать ответ узла
}

