// ближайший потомок с тегом: BFS без рекурсии и без мусора
readonly Queue<Transform> queue = new Queue<Transform>(64);

Transform FindNearest(Transform root, string tag) {
    queue.Clear();
    queue.Enqueue(root);
    while (queue.Count > 0) {
        var t = queue.Dequeue();
        if (t.CompareTag(tag)) return t;        // CompareTag не создаёт строку
        for (int i = 0; i < t.childCount; i++)
            queue.Enqueue(t.GetChild(i));       // не foreach: без перечислителя
    }
    return null;
}
